    private class Component(val count: Int, val added: Boolean, val removed: Boolean, val previous: Component?)

import Foundation

/// prism-core's `Prism.tokenize`, over the grammars
/// scripts/generate-prism-grammars.cjs writes out with their patterns
/// rewritten for ICU. Offsets are UTF-16, as in JavaScript.
public enum Prism {
    /// What `Prism.tokenize` returns: plain text, or a named token over
    /// its content. Ranges are into the text that was tokenized.
    public indirect enum Node: Equatable, Sendable {
        case text(location: Int, length: Int)
        case token(String, [Node])
    }

    /// Whether a grammar exists for a language id.
    public static func hasGrammar(_ language: String?) -> Bool {
        guard let language else { return false }
        return PrismGrammarTable.languages[language] != nil
    }

    /// The text's tokens in `language`'s grammar; nil without one. Throws
    /// only if a pattern fails to compile, which the tests rule out.
    public static func tokenize(_ text: String, language: String) throws -> [Node]? {
        guard let index = PrismGrammarTable.languages[language] else { return nil }
        let source = text as NSString
        return try Tokenizer(text: source, base: 0).tokenize(grammar: index)
    }

    // MARK: Grammars

    struct Pattern {
        var source: Int
        var ignoreCase: Bool
        var lookbehind: Bool
        var greedy: Bool
        /// A grammar index, or -1.
        var inside: Int
    }

    struct Token {
        var name: String
        var patterns: [Pattern]
    }

    /// The parsed table: grammars, and pattern sources with their macros
    /// expanded. Patterns compile on first use.
    final class Table: @unchecked Sendable {
        let grammars: [[Token]]
        let sources: [String]
        private let lock = NSLock()
        private var compiled: [Int: NSRegularExpression] = [:]

        init() {
            // A multi-line literal drops its last newline: one line each.
            sources = PrismGrammarTable.patterns.split(separator: "\n", omittingEmptySubsequences: false).map { line in
                var source = String(line)
                for (name, value) in PrismGrammarTable.macros {
                    source = source.replacingOccurrences(of: name, with: value)
                }
                return source
            }
            var grammars: [[Token]] = []
            for line in PrismGrammarTable.grammars.split(separator: "\n") {
                switch line.first {
                case "@":
                    grammars.append([])
                case "=":
                    grammars[grammars.count - 1].append(Token(name: String(line.dropFirst()), patterns: []))
                case "~":
                    let fields = line.dropFirst().split(separator: " ")
                    let flags = Array(fields[0])
                    let pattern = Pattern(
                        source: Int(fields[2])!,
                        ignoreCase: flags[0] == "i",
                        lookbehind: flags[1] == "l",
                        greedy: flags[2] == "g",
                        inside: Int(fields[1])!
                    )
                    let last = grammars.count - 1
                    grammars[last][grammars[last].count - 1].patterns.append(pattern)
                default:
                    break
                }
            }
            self.grammars = grammars
        }

        func regex(_ pattern: Pattern) throws -> NSRegularExpression {
            let key = pattern.source * 2 + (pattern.ignoreCase ? 1 : 0)
            lock.lock()
            defer { lock.unlock() }
            if let regex = compiled[key] { return regex }
            let regex = try NSRegularExpression(pattern: sources[pattern.source], options: pattern.ignoreCase ? [.caseInsensitive] : [])
            compiled[key] = regex
            return regex
        }
    }

    static let table = Table()

    // MARK: Tokenizing

    /// Prism's LinkedList, matchGrammar and matchPattern over one text.
    /// Nodes live in arrays; index 0 is the head and 1 the tail.
    private final class Tokenizer {
        private enum Value {
            /// Text from `location` in this tokenizer's text.
            case text(Int, Int)
            case token(name: String, content: [Node], length: Int)

            var length: Int {
                switch self {
                case .text(_, let length): length
                case .token(_, _, let length): length
                }
            }
        }

        /// matchGrammar's `rematch`: which pattern caused the re-match, and
        /// how far it has to look.
        private final class Rematch {
            let token: Int
            let pattern: Int
            var reach: Int

            init(token: Int, pattern: Int, reach: Int) {
                self.token = token
                self.pattern = pattern
                self.reach = reach
            }
        }

        private let text: NSString
        /// The same text as a String bridged from it, which is what
        /// NSRegularExpression takes; on Apple platforms it hands the
        /// NSString straight back.
        private let string: String
        private let length: Int
        /// Where this text starts in the text first tokenized.
        private let base: Int
        private var values: [Value?] = [nil, nil]
        private var next: [Int] = [1, -1]
        private var previous: [Int] = [-1, 0]
        private var count = 0
        private struct NodeKey: Hashable {
            let location: Int
            let length: Int
        }
        private var nodeTexts: [NodeKey: String] = [:]
        private let head = 0
        private let tail = 1

// Observe macOS system capability changes for the Happy CLI.
//
// This helper is intentionally read-only. It does not create power
// assertions, acknowledge sleep notifications, or initiate a power event.

#include <CoreFoundation/CoreFoundation.h>
#include <IOKit/IOKitLib.h>
#include <IOKit/IOMessage.h>
#include <IOKit/pwr_mgt/IOPM.h>

#include <signal.h>
#include <stdio.h>
#include <unistd.h>

static volatile sig_atomic_t shouldStop = 0;

static void stopHandler(int signalNumber) {
    (void)signalNumber;
    shouldStop = 1;
}

static void emitCapabilityChange(
    const struct IOPMSystemCapabilityChangeParameters *change
) {
    const char *phase = "unknown";

    if ((change->changeFlags & kIOPMSystemCapabilityDidChange) != 0) {
        phase = "did-change";
    } else if ((change->changeFlags & kIOPMSystemCapabilityWillChange) != 0) {
        phase = "will-change";
    } else if (change->changeFlags == 0 && change->fromCapabilities == 0) {
        phase = "initial";
    }

    // Keep stdout machine-readable: one JSON object per line and no other
    // stdout output. The CLI only consumes the `to` capability mask.
    printf(
        "{\"event\":\"capability-change\",\"phase\":\"%s\",\"flags\":%u,\"from\":%u,\"to\":%u}\n",
        phase,
        change->changeFlags,
        change->fromCapabilities,
        change->toCapabilities
    );
    fflush(stdout);
}

static void capabilityChanged(
    void *refcon,
    io_service_t service,
    uint32_t messageType,
    void *messageArgument
) {
    (void)refcon;
    (void)service;

    if (messageType != kIOMessageSystemCapabilityChange || messageArgument == NULL) {
        return;
    }

    emitCapabilityChange(
        (const struct IOPMSystemCapabilityChangeParameters *)messageArgument
    );
}

int main(void) {
    signal(SIGINT, stopHandler);
    signal(SIGTERM, stopHandler);

    const pid_t parentPid = getppid();
    if (parentPid <= 1) {
        fputs("invalid parent process\n", stderr);
        return 1;
    }

    // A null main port asks IOKit for its default port and avoids depending
    // on the macOS 12-only spelling of that constant.
    IONotificationPortRef notificationPort = IONotificationPortCreate(MACH_PORT_NULL);
    if (notificationPort == NULL) {
        fputs("IONotificationPortCreate failed\n", stderr);
        return 1;
    }

    io_service_t rootDomain = IOServiceGetMatchingService(
        MACH_PORT_NULL,
        IOServiceMatching("IOPMrootDomain")
    );
    if (rootDomain == IO_OBJECT_NULL) {
        fputs("IOPMrootDomain not found\n", stderr);
        IONotificationPortDestroy(notificationPort);
        return 1;
    }

    io_object_t notification = IO_OBJECT_NULL;
    kern_return_t result = IOServiceAddInterestNotification(
        notificationPort,
        rootDomain,
        kIOPriorityPowerStateInterest,
        capabilityChanged,
        NULL,
        &notification
    );
    if (result != KERN_SUCCESS) {
        fprintf(stderr, "IOServiceAddInterestNotification failed: 0x%x\n", result);
        IOObjectRelease(rootDomain);
        IONotificationPortDestroy(notificationPort);
        return 1;
    }

    CFRunLoopRef runLoop = CFRunLoopGetCurrent();
    CFRunLoopSourceRef source = IONotificationPortGetRunLoopSource(notificationPort);
    if (source == NULL) {
        fputs("IOKit notification run-loop source unavailable\n", stderr);
        IOObjectRelease(notification);
        IOObjectRelease(rootDomain);
        IONotificationPortDestroy(notificationPort);
        return 1;
    }
    CFRunLoopAddSource(runLoop, source, kCFRunLoopDefaultMode);

    while (!shouldStop) {
        if (getppid() != parentPid) {
            break;
        }
        CFRunLoopRunInMode(kCFRunLoopDefaultMode, 1.0, true);
    }

    CFRunLoopRemoveSource(runLoop, source, kCFRunLoopDefaultMode);
    IOObjectRelease(notification);
    IOObjectRelease(rootDomain);
    IONotificationPortDestroy(notificationPort);
    return 0;
}

:root {
  color-scheme: light;
  --bg-top: #f6efe4;
  --bg-bottom: #d9e7f5;
  --panel: rgba(255, 250, 245, 0.88);
  --panel-strong: #fff8f0;
  --ink: #1d2430;
  --muted: #6b7280;
  --accent: #d46a4c;
  --accent-strong: #b94d34;
  --border: rgba(29, 36, 48, 0.1);
  --shadow: 0 20px 60px rgba(43, 50, 67, 0.16);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: Georgia, "Times New Roman", serif;
  color: var(--ink);
  background: linear-gradient(160deg, var(--bg-top), var(--bg-bottom));
}

button,
input {
  font: inherit;
}

.app-shell {
  width: min(1080px, calc(100vw - 32px));
  margin: 0 auto;
  min-height: 100vh;
  display: grid;
  grid-template-columns: 1fr 1.15fr;
  gap: 24px;
  align-items: center;
  padding: 32px 0;
}

.hero-panel,
.todo-panel {
  background: var(--panel);
  backdrop-filter: blur(14px);
  border: 1px solid var(--border);
  border-radius: 28px;
  box-shadow: var(--shadow);
}

.hero-panel {
  padding: 36px;
}

.eyebrow {
  margin: 0 0 12px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 0.78rem;
  color: var(--accent-strong);
}

h1 {
  margin: 0;
  font-size: clamp(2.3rem, 5vw, 4rem);
  line-height: 0.95;
}

.hero-copy {
  margin: 18px 0 0;
  max-width: 28rem;
  font-size: 1.1rem;
  line-height: 1.6;
  color: var(--muted);
}

.stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 28px;
}

.stats article {
  padding: 18px;
  border-radius: 20px;
  background: var(--panel-strong);
}

.stats span {
  display: block;
  font-size: 2rem;
  font-weight: 700;
}

.stats p {
  margin: 8px 0 0;
  color: var(--muted);
}

.todo-panel {
  padding: 24px;
}

.todo-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
}

.todo-form input {
  width: 100%;
  padding: 16px 18px;
  border-radius: 16px;
  border: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.9);
}

.todo-form button,
.ghost-button,
.filter,
.delete-button {
  border: 0;
  border-radius: 14px;
  cursor: pointer;
  transition: transform 140ms ease, background 140ms ease, color 140ms ease;
}

.todo-form button {
  padding: 0 18px;
  background: var(--accent);
  color: #fff;
}

.toolbar {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  margin: 18px 0;
}

.filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

